def transform(grid):
    h, w = len(grid), len(grid[0])
    # The colored strokes lie on diagonals of constant row-column.
    # Their offsets determine the phase of the repeating diagonal pattern.
    anchors = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                anchors[r - c] = grid[r][c]

    period = max(anchors) - min(anchors) + 1
    # Find the shortest period that gives distinct consistent phases for
    # the marked diagonal colors.
    for p in range(1, period + 1):
        if all(anchors[a] == anchors[b]
               for a in anchors for b in anchors
               if (a - b) % p == 0):
            period = p
            break

    phase_color = {k % period: v for k, v in anchors.items()}
    for phase in range(period):
        if phase not in phase_color:
            nearest = min(anchors, key=lambda k: min(
                (k - phase) % period, (phase - k) % period))
            phase_color[phase] = anchors[nearest]

    return [[phase_color[(r - c) % period] for c in range(w)]
            for r in range(h)]
